import {S,Q,T,P,B,assemble} from './ramadevi-content.mjs';
const rows=[
 S('Espacios vectoriales y aplicaciones lineales','Vectores y bases','3.1','29–33','De una combinación de vectores a las matrices que describen una simetría.',[
 ['La estructura que se conserva','Trabajamos sobre los complejos salvo que se indique un ejemplo real. Las combinaciones lineales definen el espacio; una condición lineal homogénea define un subespacio y una condición inhomogénea suele definir un conjunto afín.',T`A(\alpha v+\beta w)=\alpha Av+\beta Aw.`],
 ['Base y rango','Una base permite escribir cada vector de forma única. El rango cuenta imágenes independientes y la nulidad cuenta combinaciones que desaparecen. Una matriz cuadrada representa una transformación invertible si y solo si su núcleo es cero.',T`v=Bc,\quad c=B^{-1}v,\qquad\dim V=\dim\ker A+\dim\operatorname{im}A.`],
 ['Cambio de coordenadas','Las columnas de B son los vectores básicos expresados en una base de referencia. La base dual extrae coordenadas; en una base oblicua, tomar productos con los mismos vectores básicos no suele hacerlo.',T`B'=BS\quad\Rightarrow\quad c'=S^{-1}c,\quad A'=S^{-1}AS.`]
 ],B(T`B=\begin{pmatrix}1&s\\0&1\end{pmatrix},\quad v=(3,1),\quad c=(3-s,1).`)+P('Con oblicuidad dos, las coordenadas son uno y uno. Reconstruir el vector como suma de las dos columnas con esos coeficientes da (3,1). El vector físico permanece igual; la lista que lo representa depende de la base. El laboratorio permite cambiar la oblicuidad y comprobar la reconstrucción.'),[
 Q('El núcleo de una aplicación lineal contiene…',['El vector cero','Solo vectores no nulos','Un dato inhomogéneo fijo'],0,'La linealidad obliga a que la imagen del vector cero sea cero.'),Q('Las columnas de B representan…',['Los vectores de la base','Los autovalores siempre','Solo las normas'],0,'La multiplicación Bc reconstruye el vector sumando columnas con los coeficientes de c.'),Q('La dimensión del núcleo más el rango es…',['La dimensión del dominio','La dimensión del codominio siempre','Cero'],0,'El teorema rango-nulidad cuenta las libertades del espacio de partida.')]),
 S('Producto escalar, adjunto y unitariedad','Métrica y adjunto','3.1','33–36','Una matriz no ortogonal puede describir una acción que conserva el producto escalar si se incluye la métrica correcta.',[
 ['Métrica de una base','El producto hermítico requiere conjugación en el primer argumento y positividad sobre vectores no nulos. En coordenadas oblicuas lo representa una matriz hermítica positiva.',T`\langle v,w\rangle=c^{\dagger}Gd,\quad G=B^{\dagger}B.`],
 ['Adjunto en coordenadas','Trasladar el operador de un argumento al otro determina su adjunto relativo a la métrica. La transpuesta sola basta únicamente en el ejemplo real con métrica identidad.',T`A^{\sharp}=G^{-1}A^{\dagger}G,\quad D(g)^{\dagger}GD(g)=G.`],
 ['Unitarizar por promedio','Para un grupo finito, promediar cualquier producto positivo sobre todas las imágenes construye uno invariante. La finitud garantiza que la suma existe y la invertibilidad asegura positividad.',T`G=\frac1{|G_{\rm grupo}|}\sum_gD(g)^{\dagger}D(g).`]
 ],P('Toma una rotación del triángulo y exprésala en una base oblicua. Su matriz deja de ser ortogonal con la métrica usual, pero conserva Gram. El laboratorio calcula ambas diferencias para distinguir un cambio del operador de un cambio de sus componentes. La conservación de norma exige declarar el producto escalar usado.'),[
 Q('Una métrica de producto escalar debe ser…',['Hermítica positiva definida','Antisimétrica','Solo diagonal'],0,'La positividad y la simetría hermítica garantizan una norma estrictamente positiva para vectores no nulos.'),Q('La condición unitaria en una métrica G es…',['D†GD=G','D+G=I','D=G'],0,'La igualdad conserva el producto escalar de cualquier par de vectores.'),Q('El promedio de métricas funciona aquí porque…',['El grupo es finito','Todas las matrices ya son diagonales','El espacio es real necesariamente'],0,'Una suma finita de normas positivas define un producto invariante por reordenamiento de los elementos.')]),
 S('Acción de grupo y representaciones','La ley de representación','3.2','36–38','Una acción lineal convierte la composición de simetrías en multiplicación de matrices.',[
 ['Homomorfismo','Las matrices deben satisfacer la ley simultáneamente para todas las parejas. La identidad y las inversas quedan entonces representadas por las matrices correspondientes.',T`D(gh)=D(g)D(h),\quad D(e)=I,\quad D(g^{-1})=D(g)^{-1}.`],
 ['Núcleo y fidelidad','El núcleo reúne las operaciones invisibles para ese espacio de estados. Una representación puede ser válida y no fiel; su dimensión tampoco coincide necesariamente con el orden del grupo.',T`\ker D=\{g:D(g)=I\},\quad D\ \text{fiel}\iff\ker D=\{e\}.`],
 ['Generadores y relaciones','Para el grupo del triángulo, una rotación y una reflexión generan toda la acción. No basta comprobar sus órdenes: también debe conservarse su relación mixta.',T`r^3=s^2=e,\ srs=r^{-1}\quad\Rightarrow\quad R^3=S^2=I,\ SRS=R^{-1}.`]
 ],P('La representación trivial asigna uno a las seis operaciones y cumple todos los productos, aunque su núcleo sea todo el grupo. El doblete plano distingue las seis matrices y es fiel. La representación de vértices tiene dimensión tres y también es fiel, pero se descompone. Fidelidad e irreducibilidad responden a preguntas distintas.'),[
 Q('La representación trivial es…',['Válida pero no fiel para un grupo no trivial','Inválida','Siempre irreducible de dimensión seis'],0,'La matriz uno conserva todos los productos, pero no distingue elementos del grupo.'),Q('El núcleo mide…',['Qué operaciones actúan como identidad','Solo la dimensión','Las clases de todos los autovalores'],0,'Los elementos del núcleo no producen cambio en ningún vector del espacio representativo.'),Q('Verificar los órdenes de dos generadores…',['No sustituye comprobar la relación mixta','Siempre basta','Prueba unitariedad'],0,'La relación entre productos de generadores distintos también forma parte de la presentación del grupo.')]),
 S('Reducibilidad, Maschke y Schur','Separar subespacios','3.3','38–41','Un subespacio invariante separa una parte de la acción; para grupos finitos sobre los complejos puede elegirse un complemento también invariante.',[
 ['Invariancia simultánea','Un subespacio debe conservarse bajo todos los elementos. Diagonalizar una sola matriz no garantiza la reducción de la representación completa.',T`D(g)W\subset W\quad\forall g.`],
 ['Complemento ortogonal','El producto escalar promediado permite probar que el complemento ortogonal de un subespacio invariante también lo es. Repetir el procedimiento produce irreducibles.',T`\langle D(g)v,w\rangle=\langle v,D(g)^{-1}w\rangle=0\quad(v\in W^\perp,w\in W).`],
 ['Schur y multiplicidad','Sobre una irreducible compleja, un operador que conmuta con todo el grupo es escalar. Si hay varias copias equivalentes, puede actuar una matriz no escalar entre las copias.',T`V=\bigoplus_\alpha\mathbb C^{m_\alpha}\otimes V_\alpha,\quad\operatorname{End}_G(V)=\bigoplus_\alpha M_{m_\alpha}(\mathbb C).`]
 ],B(T`\mathbb C^3=\langle(1,1,1)\rangle\oplus\{(x,y,z):x+y+z=0\}.`)+P('Las permutaciones del triángulo conservan la recta uniforme y el plano de suma cero. El primero es trivial y el segundo es el doblete. El laboratorio muestra las componentes; ninguna operación mezcla ambos sectores. La descomposición es una propiedad conjunta de las seis matrices.'),[
 Q('Un subespacio invariante debe conservarse…',['Bajo todo el grupo','Solo bajo un generador elegido sin más','Solo bajo la identidad'],0,'La definición exige invariancia para cada operador de la representación.'),Q('Schur escalar se formula aquí sobre…',['Los complejos y una irreducible','Toda matriz real','Cualquier representación reducible'],0,'El campo complejo y la irreducibilidad permiten usar un autovalor para probar que el operador es escalar.'),Q('Dos copias equivalentes permiten…',['Mezcla en el espacio de multiplicidades','Una sola matriz escalar obligatoria','Perder la ley de grupo'],0,'El conmutante puede actuar como una matriz sobre las copias sin alterar la acción irreducible.')]),
 S('Irreducibles de grupos puntuales','Caracteres de C₃v','3.4','41–44','La tabla de caracteres de C₃v conecta operaciones moleculares con tipos de simetría.',[
 ['Clases y caracteres','C₃v es isomorfo al grupo de permutaciones de tres objetos. Sus clases tienen tamaños uno, dos y tres. El carácter es constante en cada clase porque la traza se conserva por similitud.',T`\chi_{A_1}=(1,1,1),\quad\chi_{A_2}=(1,1,-1),\quad\chi_E=(2,-1,0).`],
 ['Dimensiones y número de clases','Hay tres irreducibles complejas porque hay tres clases. La suma de cuadrados de dimensiones debe recuperar el orden del grupo.',T`1^2+1^2+2^2=6.`],
 ['Acción sobre funciones','Una coordenada axial puede transformarse como el singlete trivial mientras las dos coordenadas del plano forman el doblete. El grupo abstracto no determina por sí solo qué espacio físico se ha elegido.',T`z\sim A_1,\qquad(x,y)\sim E\quad\text{para el eje principal de }C_{3v}.`]
 ],P('Una reflexión plana tiene un autovalor uno y otro menos uno en el doblete, así que su traza es cero. Un giro de ciento veinte grados tiene traza menos uno. El laboratorio permite elegir la operación y comparar matriz y carácter, sin identificar fidelidad con valor de la traza.'),[
 Q('El carácter de E en una reflexión es…',['Cero','Dos','Menos uno'],0,'Los autovalores uno y menos uno se cancelan en la traza.'),Q('Los tamaños de clase entran en…',['Los productos escalares de caracteres','La dimensión espacial obligatoria','Solo el determinante'],0,'Cada valor de clase representa tantos elementos como su tamaño y debe ponderarse al promediar.'),Q('C₃v tiene cuántas irreducibles complejas?',['Tres','Seis','Dos'],0,'El número de irreducibles complejas de un grupo finito coincide con su número de clases de conjugación.')]),
 S('La representación regular','Todas las irreducibles','3.5','44–45','Multiplicar los elementos del grupo por la izquierda genera una representación que contiene todos sus tipos irreducibles.',[
 ['Una base por elemento','Cada columna indica dónde termina el elemento que etiqueta esa columna. El tamaño de la matriz regular es el orden del grupo, aunque otras representaciones tengan dimensiones menores.',T`D_{\rm reg}(g)e_h=e_{gh}.`],
 ['Cuenta puntos fijos','Una multiplicación izquierda no trivial no fija ningún elemento del grupo. La identidad fija todos.',T`\chi_{\rm reg}(e)=|G|,\quad\chi_{\rm reg}(g)=0\ (g\ne e).`],
 ['Calcula multiplicidades','El producto escalar con un carácter irreducible recibe contribución solo de la identidad. La multiplicidad es la dimensión del tipo.',T`m_\alpha=d_\alpha,\quad D_{\rm reg}(C_{3v})=A_1\oplus A_2\oplus2E.`]
 ],P('En seis dimensiones aparecen dos singletes y dos copias del doblete. La dimensión total es uno más uno más cuatro. El laboratorio muestra una matriz de permutación regular; una sola reflexión fija cero vectores básicos aunque tenga autovectores con autovalor uno formados por combinaciones de ellos.'),[
 Q('La multiplicidad de un tipo en la regular es…',['Su dimensión','Siempre uno','El tamaño de su clase'],0,'La fórmula de multiplicidad aplicada al carácter regular deja el valor del carácter irreducible en la identidad.'),Q('Un elemento no trivial fija vectores básicos regulares?',['No','Siempre uno','Todos'],0,'La igualdad gh=h implica g igual a identidad.'),Q('La regular de C₃v tiene dimensión…',['Seis','Tres','Dos'],0,'Tiene un vector básico por cada elemento del grupo.')]),
 S('Producto tensorial de representaciones','Dos grados de libertad','3.6','45–46','El tensor combina dos espacios y permite descomponer estados de un sistema compuesto.',[
 ['Multiplica dimensiones','Cada par de vectores básicos define un vector del producto. La acción sobre ambos factores se aplica al mismo elemento del grupo.',T`D_{V\otimes W}(g)=D_V(g)\otimes D_W(g),\quad\dim(V\otimes W)=d_Vd_W.`],
 ['Multiplica caracteres','La traza del producto de Kronecker es el producto de trazas. Esta identidad reduce el cálculo de multiplicidades a números de clase.',T`\chi_{V\otimes W}(g)=\chi_V(g)\chi_W(g).`],
 ['El doblete al cuadrado','El carácter del tensor no coincide con el de la suma de dos dobletes, aunque ambas tengan dimensión cuatro.',T`E\otimes E=A_1\oplus A_2\oplus E,\quad\chi=(4,1,0).`]
 ],P('En la base de pares de coordenadas, la combinación xx+yy es un singlete simétrico, xy−yx es alternante y las dos combinaciones xx−yy, xy+yx forman el doblete. En un espacio tensorial abstracto los dos símbolos de cada producto pertenecen a factores distintos; no se anula el alternante como sucedería al multiplicar números ordinarios iguales.'),[
 Q('La dimensión del tensor de dos dobletes es…',['Cuatro','Dos','Ocho'],0,'Las dimensiones de los factores se multiplican.'),Q('La combinación alternante xy−yx en el tensor…',['Puede ser no nula porque los factores son distintos','Es siempre cero como producto de números','Es la identidad'],0,'Los símbolos representan pares ordenados de vectores básicos, no productos conmutativos de escalares.'),Q('E⊗E contiene…',['Dos singletes y un doblete','Solo dos dobletes','Una irreducible de dimensión cuatro'],0,'El carácter (4,1,0) se descompone como A1 más A2 más E.')]),
 S('Ortogonalidad de caracteres','Promediar sobre el grupo','3.7','46–48','Los caracteres irreducibles forman un sistema ortonormal de funciones de clase con un producto escalar ponderado.',[
 ['Promedio correcto','La conjugación del primer factor permite trabajar con caracteres complejos. Los tamaños de clase sustituyen la suma sobre elementos.',T`\langle\chi,\psi\rangle=\frac1{|G|}\sum_g\chi(g)^*\psi(g)=\frac16(\chi_e^*\psi_e+2\chi_r^*\psi_r+3\chi_s^*\psi_s).`],
 ['Origen en Schur','Promediar una aplicación entre dos irreducibles produce un entrelazador. Para tipos distintos se anula; para el mismo tipo es escalar. De ahí se obtienen ortogonalidad matricial y de caracteres.',T`\langle\chi_\alpha,\chi_\beta\rangle=\delta_{\alpha\beta}.`],
 ['No es un promedio sin pesos','La identidad, dos giros y tres reflexiones no aportan el mismo número de elementos. Ignorar estos pesos destruye la ortogonalidad.',T`\langle A_1,E\rangle=(2+2(-1)+3(0))/6=0.`]
 ],P('El laboratorio calcula la contribución de cada clase al producto escalar. Cambia el carácter de comparación y verifica norma uno para cada irreducible, producto cero para tipos distintos. Las entradas de la tabla son trazas; el peso pertenece a la medida sobre el grupo, no a un nuevo valor del carácter.'),[
 Q('El peso de la clase de reflexiones en C₃v es…',['Tres','Uno','Dos'],0,'Hay tres elementos en esa clase y todos contribuyen con el mismo valor de carácter.'),Q('El conjugado del primer carácter es…',['Necesario en el caso complejo','Siempre prescindible','Un cambio de grupo'],0,'El producto escalar hermítico necesita conjugación; los ejemplos reales solo ocultan esa diferencia.'),Q('El producto de caracteres de tipos distintos vale…',['Cero tras promediar correctamente','Siempre uno','La suma de dimensiones'],0,'La ortogonalidad se obtiene para las irreducibles con el producto escalar del grupo.')]),
 S('Multiplicidades y criterio de irreducibilidad','Descomponer un carácter','3.7','48–51','La tabla permite contar copias de cada tipo sin adivinar una base adaptada.',[
 ['Proyecta el carácter','La multiplicidad es un entero no negativo cuando el carácter procede de una representación válida. Una lista arbitraria de números puede no ser un carácter.',T`m_\alpha=\langle\chi_\alpha,\chi\rangle,\quad\chi=\sum_\alpha m_\alpha\chi_\alpha.`],
 ['Norma y conmutante','La norma es la suma de cuadrados de multiplicidades. Vale uno exactamente para una irreducible en este contexto complejo finito.',T`\langle\chi,\chi\rangle=\sum_\alpha m_\alpha^2.`],
 ['Comprueba la dimensión','Sumar multiplicidad por dimensión debe recuperar el carácter de la identidad. Es un control independiente de las otras clases.',T`\chi=(3,0,1)\Rightarrow m=(1,0,1),\quad3=1+2.`]
 ],P('Para el tensor de dos dobletes, el carácter (4,1,0) da una copia de cada tipo. Su norma es tres, no cuatro: cuenta componentes irreducibles con sus multiplicidades al cuadrado y no la dimensión del espacio. El laboratorio ofrece caracteres conocidos para evitar interpretar como representación cualquier vector numérico.'),[
 Q('La norma del carácter E⊗E vale…',['Tres','Cuatro','Uno'],0,'Contiene tres tipos con multiplicidad uno, así que la suma de cuadrados es tres.'),Q('Una multiplicidad negativa indica…',['Que los datos o la interpretación no forman ese carácter válido','Una nueva irreducible física','Solo un cambio de base'],0,'Las multiplicidades cuentan copias de subespacios y no pueden ser negativas.'),Q('La dimensión se recupera mediante…',['La suma de multiplicidades por dimensiones','La suma de multiplicidades al cuadrado siempre','Solo la norma del carácter'],0,'Cada copia irreducible aporta su propia dimensión al espacio total.')]),
 S('Proyectores y bases adaptadas','Extraer sectores','3.7','50–52','Un proyector de carácter separa todas las copias de un tipo presentes en la representación.',[
 ['Construye el operador','La fórmula utiliza el carácter conjugado y el promedio de matrices. En una representación unitaria da un proyector ortogonal.',T`P_\alpha=\frac{d_\alpha}{|G|}\sum_g\chi_\alpha(g)^*D(g).`],
 ['Idempotencia y completitud','Aplicar dos veces no cambia el resultado de la primera aplicación. Sectores distintos se anulan entre sí y suman la identidad.',T`P_\alpha^2=P_\alpha,\quad P_\alpha P_\beta=0\ (\alpha\ne\beta),\quad\sum_\alpha P_\alpha=I.`],
 ['No separa copias equivalentes','El rango recoge el sector isotípico completo. Un vector de prueba puede tener proyección cero aunque el tipo exista en otro vector.',T`\operatorname{rango}P_\alpha=m_\alpha d_\alpha.`]
 ],B(T`P_{A_1}=J/3,\quad P_E=I-J/3,\quad v=(1,2,6)\Rightarrow v_{A_1}=(3,3,3),\ v_E=(-2,-1,3).`)+P('Las componentes se suman y son ortogonales. El proyector alternante es cero en la acción de vértices porque ese tipo no aparece; no hace falta buscar una cuarta dirección. El laboratorio permite cambiar el vector y el sector.'),[
 Q('Aplicar dos veces un proyector da…',['El mismo resultado','El doble del resultado','Cero siempre'],0,'La idempotencia es la igualdad entre el cuadrado del operador y él mismo.'),Q('Su rango puede ser mayor que dα cuando…',['Hay varias copias equivalentes','El carácter es cero en la identidad','La representación no existe'],0,'El proyector central recoge todas las copias de ese tipo a la vez.'),Q('El proyector A₂ de la acción de vértices es…',['Cero','De rango uno siempre','La inversión'],0,'El carácter de vértices contiene A1 y E pero ninguna copia de A2.')]),
 S('Productos directos y paridad','Factores independientes','3.8','52–54','Las irreducibles del producto de dos grupos finitos se construyen como productos externos.',[
 ['Acción independiente','Cada matriz depende de su propio elemento. Las dimensiones se multiplican y la ortogonalidad de caracteres factoriza entre ambos grupos.',T`(D\boxtimes E)(g,h)=D(g)\otimes E(h),\quad\chi(g,h)=\chi_D(g)\chi_E(h).`],
 ['Añadir un factor de orden dos','Cada irreducible adquiere dos etiquetas de paridad. Multiplicar por un signo no duplica la dimensión de su espacio.',T`C_{3v}\times C_2:\quad A_1^\pm,A_2^\pm,E^\pm,\quad\sum d_\alpha^2=12.`],
 ['Restringir puede reducir','Si se identifica el mismo elemento en dos factores iguales, el producto externo se restringe al subgrupo diagonal y puede volverse reducible.',T`\operatorname{Res}_{\rm diag}(E\boxtimes E)=A_1\oplus A_2\oplus E.`]
 ],P('El doblete impar tiene matrices iguales a las del doblete en el elemento identidad del segundo factor y sus negativas en el otro elemento. Sigue teniendo dimensión dos. La etiqueta registra cómo responde al factor añadido, como la inversión central en una realización física apropiada, sin confundirla con un nuevo grado de libertad de dos estados.'),[
 Q('Añadir una etiqueta de paridad a un doblete cambia su dimensión a…',['Dos','Cuatro','Uno'],0,'La representación del factor binario es unidimensional y solo multiplica por un signo.'),Q('En el producto externo los elementos de los factores son…',['Independientes','Siempre iguales','Siempre inversos'],0,'Cada grupo actúa sobre su propio espacio y sus elementos se eligen por separado.'),Q('Una restricción a un subgrupo puede…',['Volver reducible una irreducible','Cambiar obligatoriamente la dimensión','Eliminar la identidad'],0,'Cambia el conjunto de operaciones exigidas para la invariancia, conservando el espacio vectorial.')]),
 S('Representaciones inducidas y reciprocidad','Inducir desde un subgrupo','3.9','54–58','Un subgrupo permite construir una representación del grupo completo mediante clases laterales y bloques.',[
 ['El espacio inducido','Elige representantes de clases laterales izquierdas. Cada clase lleva una copia del espacio de la representación del subgrupo.',T`\dim\operatorname{Ind}_H^G\theta=[G:H]\dim\theta.`],
 ['Construye las matrices','La entrada de bloques es cero si el elemento transformado no vuelve al subgrupo. Si vuelve, se evalúa allí la representación original. Las convenciones de representantes deben mantenerse en todos los productos.',T`D(g)_{ij}=\begin{cases}\theta(t_i^{-1}gt_j),&t_i^{-1}gt_j\in H,\\0,&\text{en otro caso}.\end{cases}`],
 ['Reciprocidad de Frobenius','La multiplicidad de un tipo de G en la inducida se obtiene restringiendo ese tipo a H y comparándolo con la representación inicial.',T`\langle\chi_\alpha,\chi_{\operatorname{Ind}\theta}\rangle_G=\langle\operatorname{Res}\chi_\alpha,\chi_\theta\rangle_H.`]
 ],B(T`H=\{e,s\}\subset C_{3v},\quad\operatorname{Ind}(1)=A_1\oplus E,\quad\operatorname{Ind}(\mathrm{sgn})=A_2\oplus E.`)+P('El índice es tres y ambas inducidas tienen dimensión tres. La trivial produce el carácter (3,0,1); la de signo da (3,0,−1). El laboratorio calcula matrices por la fórmula de clases y comprueba el carácter. Cambiar representantes cambia la base, no el tipo de representación inducida.'),[
 Q('Inducir una representación unidimensional desde un subgrupo de índice tres produce dimensión…',['Tres','Uno','Seis necesariamente'],0,'El espacio contiene una copia de la representación original por cada clase lateral.'),Q('La inducida de signo del ejemplo contiene…',['A₂ y E','Solo A₁','Tres copias de E'],0,'La restricción del doblete contiene ambos signos y el singlete alternante aporta la otra copia requerida.'),Q('Cambiar representantes de clases laterales cambia…',['La realización en una base, conservando equivalencia','El orden del grupo','La dimensión inducida'],0,'Los representantes eligen coordenadas para las copias; no cambian el espacio inducido como representación abstracta.')])
];
export const ramadevi3=assemble(rows);
